import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";
import { format } from "prettier";
import { checkContract } from "./check-contract.mjs";

const output = new URL("../src/api/schema.d.ts", import.meta.url);
const header =
  "/**\n * This file was auto-generated by openapi-typescript.\n * Do not make direct changes to the file.\n */\n\n";

export async function generateAPITypes() {
  const spec = checkContract();
  // openapi-typescript may normalize discriminator properties. Keep the source untouched.
  const declarations = astToString(await openapiTS(structuredClone(spec)));
  return format(header + declarations, { parser: "typescript" });
}

export async function checkAPITypes() {
  const expected = await generateAPITypes();
  if (!fs.existsSync(output))
    throw Error("API types are missing. Run corepack pnpm generate:api.");
  const actual = fs.readFileSync(output, "utf8").replaceAll("\r\n", "\n");
  if (actual !== expected)
    throw Error(
      "Generated API types are stale. Run corepack pnpm generate:api.",
    );
}

if (
  process.argv[1] &&
  pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url
) {
  if (process.argv.includes("--check")) {
    await checkAPITypes();
    console.log("Generated API types match the approved OpenAPI contract.");
  } else {
    fs.writeFileSync(output, await generateAPITypes());
    console.log(
      "Generated src/api/schema.d.ts from docs/openapi.json; the contract was not modified.",
    );
  }
}
